25	            className="fixed top-0 left-0 h-full w-72 bg-white dark:bg-[#18181B] z-50 shadow-2xl flex flex-col"
26	          >
27	            <div className="flex items-center justify-between px-5 py-4 border-b border-[#E4E4E7] dark:border-[#3F3F46]">
