29	              <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-[#F4F4F5] dark:hover:bg-[#27272A] text-[#71717A] dark:text-[#A1A1AA]">
30	                <Icon name="X" size={18} />
31	              </button>
32	            </div>
33	            <nav className="flex-1 overflow-y-auto px-3 py-3 flex flex-col gap-1">
34	              {links.map((l) => (
35	                <div key={l.path} className={`relative flex items-center rounded-xl transition-colors ${
36	                    l.path === activePath ? 'text-white bg-[#FF441F]' : 'text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#F4F4F5] dark:hover:bg-[#27272A]'
37	                  }`}>
38	                  <button onClick={() => ir(l.path)}
39	                    className="flex-1 flex items-center justify-between text-left pl-4 pr-2 py-2.5 text-sm font-semibold min-w-0">
40	                    {l.label}
41	                    {l.path === '/restaurante/motoboys' && pendentesMotoboy > 0 && (
42	                      <span className="min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full ml-2">
43	                        {pendentesMotoboy}
44	                      </span>
45	                    )}
46	                  </button>
47	                  {onToggleFavorito && (
48	                    <button onClick={() => onToggleFavorito(l.path)}
