import React from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import Icon from '../AppIcon';

// Menu lateral só pra desktop/telas grandes (md+) — substitui a barra horizontal de
// botões que ficava poluída com muitos links. Mobile continua com o próprio menu de cada
// página (hamburger + lista já existente), este componente nunca renderiza abaixo de md.
const RestauranteSidebar = ({ open, onClose, links, activePath, pendentesMotoboy = 0, slugLoja, onSair, onMeuPerfil, isFavorito, onToggleFavorito }) => {
  const navigate = useNavigate();
  const ir = (path) => { navigate(path); onClose(); };

  return (
    <AnimatePresence>
      {open && (
        <div className="hidden md:block">
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/40 z-40"
            onClick={onClose}
          />
          <motion.div
            initial={{ x: -320, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -320, opacity: 0 }}
            transition={{ type: 'tween', duration: 0.2 }}
            className="fixed top-0 left-0 h-full w-72 bg-white dark:bg-[#18181B] z-50 shadow-2xl flex flex-col"
          >
            <div className="flex items-center justify-between px-5 py-4 border-b border-[#E4E4E7] dark:border-[#3F3F46]">
              <p className="font-bold text-[#18181B] dark:text-[#F4F4F5]">Menu</p>
              <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-[#F4F4F5] dark:hover:bg-[#27272A] text-[#71717A] dark:text-[#A1A1AA]">
                <Icon name="X" size={18} />
              </button>
            </div>
            <nav className="flex-1 overflow-y-auto px-3 py-3 flex flex-col gap-1">
              {links.map((l) => (
                <div key={l.path} className={`relative flex items-center rounded-xl transition-colors ${
                    l.path === activePath ? 'text-white bg-[#FF441F]' : 'text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#F4F4F5] dark:hover:bg-[#27272A]'
                  }`}>
                  <button onClick={() => ir(l.path)}
                    className="flex-1 flex items-center justify-between text-left pl-4 pr-2 py-2.5 text-sm font-semibold min-w-0">
                    {l.label}
                    {l.path === '/restaurante/motoboys' && pendentesMotoboy > 0 && (
                      <span className="min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full ml-2">
                        {pendentesMotoboy}
                      </span>
                    )}
                  </button>
                  {onToggleFavorito && (
                    <button onClick={() => onToggleFavorito(l.path)}
                      className={`p-2 mr-1 rounded-lg flex-shrink-0 ${l.path === activePath ? 'hover:bg-white/20' : 'hover:bg-[#E4E4E7] dark:hover:bg-[#3F3F46]'}`}
                      title={isFavorito?.(l.path) ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}>
                      <Icon name="Star" size={15} className={isFavorito?.(l.path) ? 'fill-current' : ''} />
                    </button>
                  )}
                </div>
              ))}
            </nav>
            {(slugLoja || onMeuPerfil || onSair) && (
              <div className="px-3 py-3 border-t border-[#E4E4E7] dark:border-[#3F3F46] flex flex-col gap-1.5">
                {slugLoja && (
                  <button onClick={() => window.open(`/r/${slugLoja}`, '_blank')}
                    className="w-full text-left px-4 py-2.5 text-sm font-semibold text-green-700 dark:text-green-400 bg-green-50 dark:bg-green-950/40 hover:bg-green-100 dark:hover:bg-green-950/60 rounded-xl border border-green-200 dark:border-green-800 flex items-center gap-2">
                    <Icon name="ExternalLink" size={14} /> Loja
                  </button>
                )}
                <button onClick={() => ir('/restaurante/config')}
                  className="w-full text-left px-4 py-2.5 text-sm font-semibold text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#F4F4F5] dark:hover:bg-[#27272A] rounded-xl border border-[#E4E4E7] dark:border-[#3F3F46] flex items-center gap-2">
                  <Icon name="Settings" size={14} /> Config
                </button>
                {onMeuPerfil && (
                  <button onClick={onMeuPerfil}
                    className="w-full text-left px-4 py-2.5 text-sm font-semibold text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#F4F4F5] dark:hover:bg-[#27272A] rounded-xl border border-[#E4E4E7] dark:border-[#3F3F46] flex items-center gap-2">
                    <Icon name="UserCircle" size={14} /> Meu Perfil
                  </button>
                )}
                {onSair && (
                  <button onClick={onSair}
                    className="w-full text-left px-4 py-2.5 text-sm font-semibold text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 rounded-xl border border-red-200 dark:border-red-800">
                    Sair
                  </button>
                )}
              </div>
            )}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

export default RestauranteSidebar;

const BASE_LINKS = [
  { label: 'Dashboard', path: '/restaurante', icon: 'LayoutDashboard' },
  { label: 'Conferências', path: '/restaurante/relatorios', icon: 'BarChart3' },
  { label: 'Produtos', path: '/restaurante/produtos', icon: 'Package' },
  { label: 'Clientes', path: '/restaurante/clientes', icon: 'UserRound' },
  { label: 'Financeiro', path: '/restaurante/financeiro', icon: 'Wallet' },
  { label: 'Caixa', path: '/restaurante/caixa', icon: 'PiggyBank' },
  { label: 'Designer', path: '/restaurante/aparencia', icon: 'Paintbrush' },
  { label: 'Cardápio Digital', path: '/restaurante/cardapio-digital', icon: 'BookOpen' },
  { label: 'Plano', path: '/restaurante/plano', icon: 'CreditCard' },
  { label: 'Sessão', path: '/restaurante/sessao', icon: 'Clock' },
];

// Servem tanto Delivery quanto Salão — só somem se a empresa não tem NENHUM módulo ativo.
const COMPARTILHADO_LINKS = [
  { label: 'Cozinha', path: '/restaurante/cozinha', icon: 'ChefHat' },
  { label: 'Combos', path: '/restaurante/combos', icon: 'Boxes' },
  { label: 'Pedidos', path: '/restaurante/pedidos', icon: 'ClipboardList' },
];

const DELIVERY_LINKS = [
  { label: 'Delivery', path: '/restaurante/delivery', icon: 'Truck' },
  { label: 'Entregas', path: '/restaurante/entregas', icon: 'Bike' },
  { label: 'Motoboys', path: '/restaurante/motoboys', icon: 'Users' },
  { label: 'Impulsionar', path: '/restaurante/impulsionar', icon: 'Rocket' },
];

const COPA_LINKS = [
  { label: 'Produção', path: '/restaurante/producao', icon: 'CookingPot' },
  { label: 'Bar', path: '/restaurante/bar', icon: 'Beer' },
];

const SALAO_LINKS = [
  { label: 'Salão', path: '/restaurante/salao', icon: 'UtensilsCrossed' },
  { label: 'Venda Balcão', path: '/restaurante/venda-balcao', icon: 'ShoppingCart' },
  { label: 'Chamada', path: '/restaurante/chamada', icon: 'Volume2' },
  { label: 'Garçons', path: '/restaurante/garcons', icon: 'Contact' },
  { label: 'Mesas', path: '/restaurante/mesas', icon: 'Table2' },
  { label: 'Impressoras', path: '/restaurante/impressoras', icon: 'Printer' },
];

// Pontos de preparo customizados (Churrasqueira, Drinks...) usam o mesmo requisito de
// visibilidade da Cozinha — precisam de algum módulo ativo pra fazer sentido no menu.
const PONTOS_PREPARO_CADASTRO = { label: 'Pontos de Preparo', path: '/restaurante/pontos-preparo', icon: 'LayoutGrid' };

// Estabelecimento tipo ≠ Restaurante (farmácia, material de construção...) chama
// o entregador de "Entregadores" no menu, em vez de "Motoboys" (termo mais
// específico de delivery de comida).
export const getRestauranteNavLinks = (moduloDelivery, moduloSalao, pontosPreparo = [], tipoRestaurante = true) => {
  const temAlgumModulo = moduloDelivery || moduloSalao;
  const deliveryLinks = tipoRestaurante
    ? DELIVERY_LINKS
    : DELIVERY_LINKS.map((l) => (l.path === '/restaurante/motoboys' ? { ...l, label: 'Entregadores' } : l));
  const links = [
    ...BASE_LINKS.slice(0, 2), // Dashboard, Relatórios
    ...(moduloDelivery ? deliveryLinks.slice(0, 1) : []), // Delivery
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(0, 1) : []), // Cozinha
    ...(temAlgumModulo ? [PONTOS_PREPARO_CADASTRO, ...pontosPreparo] : []), // Cadastro + pontos criados
    ...(moduloSalao ? COPA_LINKS : []), // Produção, Bar
    ...BASE_LINKS.slice(2, 3), // Produtos
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(1) : []), // Combos, Pedidos
    ...(moduloDelivery ? deliveryLinks.slice(1) : []), // Entregas, Motoboys/Entregadores
    ...BASE_LINKS.slice(3), // Clientes...Sessão
    ...(moduloSalao ? SALAO_LINKS : []), // Salão, Garçons, Impressoras
  ];
  // Menu lateral em ordem alfabética (pedido do usuário) — a ordem acima só
  // controla quais links entram conforme os módulos ativos. Dashboard fica
  // fixo no topo, fora da ordenação.
  const [dashboard, resto] = [links.find((l) => l.path === '/restaurante'), links.filter((l) => l.path !== '/restaurante')];
  resto.sort((a, b) => a.label.localeCompare(b.label, 'pt-BR'));
  return dashboard ? [dashboard, ...resto] : resto;
};

